fixed_code:
import logging
logger = logging.getLogger(__name__)

def sync_records(primary_db, replica_db):
    try:
        records = primary_db.fetch_uncommitted()
        replica_db.write_batch(records)
    except Exception as exc:
        logger.error("Record synchronization failed: %s", exc, exc_info=True)
        raise
